<?php
require_once 'config/database.php';require_once 'includes/auth.php';require_once 'includes/functions.php';require_login();$uid=current_user()['user_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$sid=(int)$_POST['session_id'];$rating=(int)$_POST['rating'];$text=trim($_POST['review_text']??'');$s=$pdo->prepare("SELECT * FROM LearningSessions WHERE session_id=? AND status='completed' AND (teacher_id=? OR learner_id=?)");$s->execute([$sid,$uid,$uid]);$session=$s->fetch();if(!$session||$rating<1||$rating>5){flash('error','Invalid review.');}else{$reviewed=$session['teacher_id']==$uid?$session['learner_id']:$session['teacher_id'];try{$q=$pdo->prepare("INSERT INTO Reviews(session_id,reviewer_id,reviewed_user_id,rating,review_text) VALUES(?,?,?,?,?)");$q->execute([$sid,$uid,$reviewed,$rating,$text]);award_if_missing($pdo,$uid,'Community Builder','Contributed a verified session review.','◆','community');flash('success','Review submitted.');}catch(PDOException $e){flash('error','You already reviewed this session.');}}redirect('reviews.php');}
$s=$pdo->prepare("SELECT ls.*,s.skill_name,u.first_name,u.last_name FROM LearningSessions ls JOIN Skills s ON s.skill_id=ls.skill_id JOIN Users u ON u.user_id=CASE WHEN ls.teacher_id=? THEN ls.learner_id ELSE ls.teacher_id END WHERE (ls.teacher_id=? OR ls.learner_id=?) AND ls.status='completed' ORDER BY ls.session_date DESC");$s->execute([$uid,$uid,$uid]);$sessions=$s->fetchAll();$title='Reviews';include 'includes/header.php';
?>
<div class="page-head"><div><div class="eyebrow">TRUST</div><h1>Reviews & ratings.</h1></div></div><div class="grid cards-2"><?php foreach($sessions as $s):?><div class="card"><h3><?=e($s['session_title'])?></h3><p class="muted"><?=e($s['skill_name'])?> with <?=e($s['first_name'].' '.$s['last_name'])?></p><form method="post" class="form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="session_id" value="<?=$s['session_id']?>"><label>Rating<select name="rating"><option>5</option><option>4</option><option>3</option><option>2</option><option>1</option></select></label><label>Review<textarea name="review_text" placeholder="How was the exchange?"></textarea></label><button class="btn">Submit review</button></form></div><?php endforeach;?></div>
<?php include 'includes/footer.php'; ?>
